from __future__ import annotations

from pathlib import Path

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from IPython.display import display


def find_repo_root(start: Path) -> Path:
    for candidate in [start, *start.parents]:
        if (candidate / "data" / "processed").exists() and (candidate / "src").exists():
            return candidate
    raise FileNotFoundError("Could not locate the repository root.")


REPO_ROOT = find_repo_root(Path.cwd().resolve())
INSTITUTIONAL_FILE = (
    REPO_ROOT
    / "data"
    / "processed"
    / "security_institutional_ties_country_anchor_year.csv"
)
ARMS_FILE = REPO_ROOT / "data" / "processed" / "sipri_arms_country_year.csv"

paths = {
    "repository_root": REPO_ROOT,
    "institutional_panel": INSTITUTIONAL_FILE,
    "arms_transfer_panel": ARMS_FILE,
}
missing_paths = [name for name, path in paths.items() if not path.exists()]
if missing_paths:
    raise FileNotFoundError(f"Required repository files are missing: {missing_paths}")

display_paths = {
    name: "." if path == REPO_ROOT else path.relative_to(REPO_ROOT).as_posix()
    for name, path in paths.items()
}
pd.Series(display_paths, name="repository_relative_path")

def resolve_column(frame: pd.DataFrame, candidates: list[str], role: str) -> str:
    matches = [column for column in candidates if column in frame.columns]
    if len(matches) != 1:
        raise ValueError(
            f"Expected exactly one {role} column from {candidates}; found {matches}. "
            f"Available columns: {frame.columns.tolist()}"
        )
    return matches[0]


INST_ISO3 = resolve_column(
    institutional_raw,
    ["country_iso3", "iso3", "ISO3"],
    "institutional ISO3",
)
INST_YEAR = resolve_column(
    institutional_raw,
    ["year", "Year"],
    "institutional year",
)
INST_ANCHOR = resolve_column(
    institutional_raw,
    ["anchor", "anchor_country", "Anchor"],
    "institutional anchor",
)
INST_SCORE = resolve_column(
    institutional_raw,
    [
        "security_institutional_score_raw",
        "institutional_score_raw",
        "score_raw",
    ],
    "institutional score",
)

required_institutional_columns = {
    INST_ISO3,
    INST_YEAR,
    INST_ANCHOR,
    INST_SCORE,
    "preferred_country_name",
}
missing_institutional_columns = (
    required_institutional_columns - set(institutional_raw.columns)
)
if missing_institutional_columns:
    raise ValueError(
        "Institutional panel is missing required columns: "
        f"{sorted(missing_institutional_columns)}"
    )

institutional = institutional_raw.rename(
    columns={
        INST_ISO3: "iso3",
        INST_YEAR: "year",
        INST_ANCHOR: "anchor",
        INST_SCORE: "institutional_anchor_score",
    }
).copy()

institutional["anchor_normalized"] = (
    institutional["anchor"].astype("string").str.strip().str.lower()
)

anchor_map = {
    "united states": "US",
    "united states of america": "US",
    "us": "US",
    "usa": "US",
    "china": "China",
    "people's republic of china": "China",
    "prc": "China",
}
institutional["anchor_standard"] = institutional["anchor_normalized"].map(
    anchor_map
)

if institutional["anchor_standard"].isna().any():
    bad = sorted(
        institutional.loc[
            institutional["anchor_standard"].isna(),
            "anchor",
        ].unique()
    )
    raise ValueError(f"Unrecognised institutional anchor labels: {bad}")

if institutional.duplicated(
    ["iso3", "year", "anchor_standard"]
).any():
    raise ValueError(
        "Duplicate institutional country-anchor-year keys detected."
    )

if institutional["institutional_anchor_score"].isna().any():
    raise ValueError("Institutional anchor scores contain missing values.")

if not institutional["institutional_anchor_score"].between(0, 1).all():
    raise ValueError("Institutional anchor scores fall outside [0, 1].")

pd.Series(
    {
        "rows": len(institutional),
        "entities": institutional["iso3"].nunique(),
        "first_year": institutional["year"].min(),
        "last_year": institutional["year"].max(),
        "anchors": ", ".join(
            sorted(institutional["anchor_standard"].unique())
        ),
        "duplicate_keys": institutional.duplicated(
            ["iso3", "year", "anchor_standard"]
        ).sum(),
    },
    name="value",

institutional_wide = (
    institutional.pivot(
        index=["iso3", "preferred_country_name", "year"],
        columns="anchor_standard",
        values="institutional_anchor_score",
    )
    .reset_index()
    .rename_axis(columns=None)
)

required_anchor_columns = {"US", "China"}
missing_anchor_columns = required_anchor_columns - set(institutional_wide.columns)
if missing_anchor_columns:
    raise ValueError(f"Missing institutional anchor columns: {missing_anchor_columns}")

institutional_wide["institutional_signed_score"] = (
    institutional_wide["US"] - institutional_wide["China"]
)

if institutional_wide[["US", "China"]].isna().any().any():
    raise ValueError("At least one institutional country-year lacks an anchor row.")
if not institutional_wide["institutional_signed_score"].between(-1, 1).all():
    raise ValueError("Signed institutional scores fall outside [-1, 1].")

display(
    institutional_wide[
        [
            "iso3",
            "preferred_country_name",
            "year",
            "US",
            "China",
            "institutional_signed_score",
        ]
    ].head()
)
institutional_wide["institutional_signed_score"].describe()

security["security_score_zero_fill"] = (
    0.5 * security["institutional_signed_score"]
    + 0.5 * security["arms_transfer_score"].fillna(0.0)
)
security["renormalization_effect"] = (
    security["security_score_baseline"] - security["security_score_zero_fill"]
)
security["renormalization_absolute_effect"] = security["renormalization_effect"].abs()
security["renormalization_sign_change"] = (
    np.sign(security["security_score_baseline"])
    != np.sign(security["security_score_zero_fill"])
)

missing_treatment_summary = pd.Series(
    {
        "affected_country_years": int(
            security["renormalization_absolute_effect"].gt(0).sum()
        ),
        "maximum_absolute_change": security[
            "renormalization_absolute_effect"
        ].max(),
        "mean_absolute_change_among_affected": security.loc[
            security["renormalization_absolute_effect"].gt(0),
            "renormalization_absolute_effect",
        ].mean(),
        "country_year_sign_changes": int(
            security["renormalization_sign_change"].sum()
        ),
    },
    name="value",
)
missing_treatment_summary

rank_specs = {
    "baseline_rank": "security_score_baseline",
    "zero_fill_rank": "security_score_zero_fill",
    "institutional_emphasis_rank": "security_score_institutional_emphasis",
    "arms_emphasis_rank": "security_score_arms_emphasis",
}
for rank_column, score_column in rank_specs.items():
    security[rank_column] = security.groupby("year")[score_column].rank(
        method="average",
        ascending=False,
    )

security["zero_fill_rank_change"] = (
    security["zero_fill_rank"] - security["baseline_rank"]
)
security["institutional_emphasis_rank_change"] = (
    security["institutional_emphasis_rank"] - security["baseline_rank"]
)
security["arms_emphasis_rank_change"] = (
    security["arms_emphasis_rank"] - security["baseline_rank"]
)

ranking_summary = pd.DataFrame(
    {
        "comparison": [
            "zero_fill",
            "institutional_emphasis",
            "arms_emphasis",
        ],
        "mean_absolute_rank_change": [
            security["zero_fill_rank_change"].abs().mean(),
            security["institutional_emphasis_rank_change"].abs().mean(),
            security["arms_emphasis_rank_change"].abs().mean(),
        ],
        "maximum_absolute_rank_change": [
            security["zero_fill_rank_change"].abs().max(),
            security["institutional_emphasis_rank_change"].abs().max(),
            security["arms_emphasis_rank_change"].abs().max(),
        ],
        "country_years_moving_10_or_more_places": [
            int(security["zero_fill_rank_change"].abs().ge(10).sum()),
            int(
                security["institutional_emphasis_rank_change"]
                .abs()
                .ge(10)
                .sum()
            ),
            int(security["arms_emphasis_rank_change"].abs().ge(10).sum()),
        ],
    }
)
ranking_summary
